/**
 * TASK: Report and control which card of a CardLayout is showing.
 *
 * The deck panel uses a CardLayout and already holds three JPanels added under
 * the card names "first", "second" and "third" (each child's getName() matches
 * its card name). CardLayout works by making exactly ONE child visible at a
 * time -- the Next and Prev buttons already call cards.next(deck) and
 * cards.previous(deck) for you.
 *
 * Complete:
 *   getVisibleCardName() -- loop over deck.getComponents() and return the name
 *                           of the one whose isVisible() is true, or "none"
 *                           if somehow none of them is.
 *   showCard(name)       -- show that card, then call refresh().
 *
 * Example: at startup getVisibleCardName() is "first" and the label reads
 *          "Card: first"; after showCard("third") it reads "Card: third".
 */
import java.awt.CardLayout;
import java.awt.Component;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class CardDeckNavigator extends JPanel {

    private final CardLayout cards = new CardLayout();
    private final JPanel deck = new JPanel(cards);
    private final JButton nextButton = new JButton("Next");
    private final JButton prevButton = new JButton("Prev");
    private final JLabel which = new JLabel("(unknown)");

    public CardDeckNavigator() {
        deck.setName("deck");
        nextButton.setName("nextButton");
        prevButton.setName("prevButton");
        which.setName("which");
        for (String name : new String[] { "first", "second", "third" }) {
            JPanel card = new JPanel();
            card.setName(name);
            deck.add(card, name);
        }
        add(deck);
        add(prevButton);
        add(nextButton);
        add(which);
        nextButton.addActionListener(e -> {
            cards.next(deck);
            refresh();
        });
        prevButton.addActionListener(e -> {
            cards.previous(deck);
            refresh();
        });
        refresh();
    }

    /** Provided: names the visible card in the label. */
    private void refresh() {
        which.setText("Card: " + getVisibleCardName());
    }

    public String getVisibleCardName() {
        // TODO: return the name of the only visible child of deck, or "none"
        return "";
    }

    public void showCard(String name) {
        // TODO: show that card in deck, then refresh()
    }
}

