public class CardDeckNavigatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Container root, String name) {
        java.awt.Component c = find(root, name);
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static int visibleCount(java.awt.Container deck) {
        int n = 0;
        for (java.awt.Component c : deck.getComponents()) {
            if (c.isVisible()) {
                n++;
            }
        }
        return n;
    }

    public static void main(String[] args) {
        try {
            CardDeckNavigator panel = new CardDeckNavigator();
            java.awt.Component deckComp = find(panel, "deck");
            javax.swing.JButton next = (find(panel, "nextButton") instanceof javax.swing.JButton)
                    ? (javax.swing.JButton) find(panel, "nextButton") : null;
            javax.swing.JButton prev = (find(panel, "prevButton") instanceof javax.swing.JButton)
                    ? (javax.swing.JButton) find(panel, "prevButton") : null;
            check("deck uses a CardLayout", true,
                    deckComp instanceof java.awt.Container
                            && ((java.awt.Container) deckComp).getLayout() instanceof java.awt.CardLayout);
            check("exactly one card is visible", 1, visibleCount((java.awt.Container) deckComp));
            check("first card shows at startup", "first", panel.getVisibleCardName());
            check("startup label", "Card: first", labelText(panel, "which"));
            if (next != null && prev != null) {
                next.doClick();
                check("next moves forward", "Card: second", labelText(panel, "which"));
                panel.showCard("third");
                check("showCard jumps straight to a card", "third", panel.getVisibleCardName());
                check("showCard updates the label", "Card: third", labelText(panel, "which"));
                check("still only one card visible", 1, visibleCount((java.awt.Container) deckComp));
                next.doClick();
                check("next wraps around to the start", "first", panel.getVisibleCardName());
                prev.doClick();
                check("prev wraps around to the end", "third", panel.getVisibleCardName());
            } else {
                failures++;
                System.out.println("FAIL  nextButton or prevButton not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

